function calculateAverageProfitLoss(transactionList, coinName) {
  let profitLoss = [];

  transactionList.forEach((transaction) => {
    if (transaction.coinName === coinName) {
      profitLoss.push(transaction.profitEarned);
    }
  });

  let averageProfitLoss = profitLoss.reduce((a, b) => a + b) / profitLoss.length;
  return averageProfitLoss;
}

function topCoinsWithHighestAverageProfitLoss(transactionList, numCoins) {
  let profitLossMap = {};
  let coins = [];

  transactionList.forEach((transaction) => {
    let coinName = transaction.coinName;
    let profitEarned = transaction.profitEarned;
    let averageProfitLoss = calculateAverageProfitLoss(transactionList, coinName);

    if (!profitLossMap[coinName]) {
      profitLossMap[coinName] = [averageProfitLoss, profitEarned];
      coins.push(coinName);
    } else {
      profitLossMap[coinName][0] = Math.max(profitLossMap[coinName][0], averageProfitLoss);
      profitLossMap[coinName][1] += profitEarned;
    }
  });

  coins.sort((a, b) => profitLossMap[b][0] - profitLossMap[a][0]);
  coins = coins.slice(0, numCoins);

  let result = [];
  for (let i = 0; i < coins.length; i++) {
    result.push({ coinName: coins[i], averageProfitLoss: profitLossMap[coins[i]][0], totalProfitEarned: profitLossMap[coins[i]][1] });
  }

  return result;
}

function topCoinsWithHighestAverageLoss(transactionList, numCoins) {
  let profitLossMap = {};
