import javax.sound.sampled.AudioFileFormat.Type;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.Clip;
import javax.sound.sampled.FloatControl;
import javax.sound.sampled.LineEvent;
import javax.sound.sampled.LineListener;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.UnsupportedAudioFileException;

public class SummerDayAudio {
    public static void main(String[] args) {
        List<AudioFileFormat.Type> fileTypes = new ArrayList<>();
        fileTypes.add(AudioFileFormat.Type.WAVE);
        fileTypes.add(AudioFileFormat.Type.MP3);
        fileTypes.add(AudioFileFormat.Type.AIFF);

        List<File> audioFiles = new ArrayList<>();
        audioFiles.add(new File("birds.wav"));
        audioFiles.add(new File("leaves.wav"));
        audioFiles.add(new File("cicadas.wav"));
        audioFiles.add(new File("children_playing.wav"));
        audioFiles.add(new File("picnic.wav"));
        audioFiles.add(new File("beach.wav"));

        Clip clip = null;
        try {
            clip = AudioSystem.getClip();
            clip.open(AudioSystem.getAudioInputStream(audioFiles.get(0)));
            clip.start();

            // Add more audio files and control their volume using FloatControl
            for (int i = 1; i < audioFiles.size(); i++) {
                File audioFile = audioFiles.get(i);
                AudioInputStream audioInputStream = AudioSystem.getAudioInputStream(audioFile);
                AudioSystem.getClip().open(audioInputStream);
                FloatControl gainControl = (FloatControl) clip.getControl(FloatControl.Type.MASTER_GAIN);
                gainControl.setValue(0.5f); // Adjust the volume level
                clip.start();
            }

            // Add a LineListener to stop the clip when it reaches the end
            clip.addLineListener(new LineListener() {
                @Override
                public void update(LineEvent event) {
                    if (event.getLine().getPosition() >= event.getLine().getFrameLength()) {
                        clip.stop();
                    }
                }
            });
        } catch (LineUnavailableException | IOException | UnsupportedAudioFileException e) {
            e.printStackTrace();
        } finally {
            if (clip != null) {
                clip.stop();
                clip.close();
            }
        }
    }
}
