        zoom_widget_->setAlignment(Qt::AlignCenter);
        zoom_widget_->setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);

        connect(zoom_widget_, &QZoomWidget::scaleChanged, this, &MatrixDisplay::updateBitmap);
    }

    void paintEvent(QPaintEvent *event) override {
