import React, { useState, useEffect } from 'react';
import { View, StyleSheet } from 'react-native';

const FocusManagerComponent = ({ children }) => {
  const [focusedIndex, setFocusedIndex] = useState(0);

  useEffect(() => {
    const handleScroll = (event) => {
      const offset = event.nativeEvent.contentOffset.y;
      const totalHeight = event.nativeEvent.layoutMeasurement.height;

      if (offset + 100 >= totalHeight) {
        setFocusedIndex(focusedIndex + 1);
      }
    };

    const focusableViews = Array.from(document.querySelectorAll('.focusableView'));
    focusableViews.forEach((view) => {
      view.addEventListener('focus', () => {
        setFocusedIndex(focusableViews.indexOf(view));
      });
    });

    const scrollView = document.querySelector('.scrollView');
    scrollView.addEventListener('scroll', handleScroll);

    return () => {
      focusableViews.forEach((view) => {
        view.removeEventListener('focus', handleScroll);
      });

      scrollView.removeEventListener('scroll', handleScroll);
    };
  }, []);

  return (
    <View style={styles.focusManager}>
      {children}
    </View>
  );
};

