```matlab
function tense = identify_tense(sentence)
    % Define the regular expressions to match each tense
    present_simple = '^(I|you|he|she|it|we|you|they) (am|is|are) (verb)$';
    present_continuous = '^(I|you|he|she|it|we|you|they) (am|is|are) (verb)ing$';
    future_simple = '^(I|you|he|she|it|we|you|they) (will) (verb)$';
    future_continuous = '^(I|you|he|she|it|we|you|they) (will) (verb)ing$';
    past_simple = '^(I|you|he|she|it|we|you|they) (had) (verb)$';
    past_continuous = '^(I|you|he|she|it|we|you|they) (had) (verb)ing$';
    present_perfect = '^(I|you|he|she|it|we|you|they) (have) (verb)ed$';
    past_perfect = '^(I|you|he|she|it|we|you|they) (had) (verb)ed$';
    future_perfect = '^(I|you|he|she|it|we|you|they) (will have) (verb)ed$';

    % Match the tense using regular expressions
    match = regexp(sentence, present_simple, 'match');
    if ~isempty(match)
        tense = 'present simple';
    elseif regexp(sentence, present_continuous, 'match')
        tense = 'present continuous';
    elseif regexp(sentence, future_simple, 'match')
        tense = 'future simple';
    elseif regexp(sentence, future_continuous, 'match')
        tense = 'future continuous';
    elseif regexp(sentence, past_simple, 'match')
        tense = 'past simple';
    elseif regexp(sentence, past_continuous, 'match')
        tense = 'past continuous';
    elseif regexp(sentence, present_perfect, 'match')
        tense = 'present perfect';
    elseif regexp(sentence, past_perfect, 'match')
        tense = 'past perfect';
    elseif regexp(sentence, future_perfect, 'match')
        tense = 'future perfect';
    else
        tense = 'unknown';
    end
end
