```java
import org.apache.poi.ss.usermodel.Workbook;
import org.apache.poi.ss.usermodel.WorkbookFactory;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Cell;
import com.opencsv.CSVWriter;
import com.opencsv.CSVWriterBuilder;
import java.io.File;
import java.io.IOException;
import java.io.Writer;

public class ExcelToCsvConverter {

    public static void main(String[] args) {
        String excelFile = "path/to/your/excel/file.xlsx";
        String csvFile = "path/to/your/csv/file.csv";

        try {
            Workbook workbook = WorkbookFactory.create(new File(excelFile));
            Sheet sheet = workbook.getSheetAt(0);
            Row row;
            Cell cell;

            Writer writer = new CSVWriterBuilder(new FileWriter(csvFile)).withSeparator(',').withQuoteChar('"').withLineEnd("\n").build();

            for (int i = 0; i < sheet.getPhysicalNumberOfRows(); i++) {
                row = sheet.getRow(i);

                for (int j = 0; j < row.getPhysicalNumberOfCells(); j++) {
                    cell = row.getCell(j);
                    writer.write(cell.toString());

                    if (j < row.getPhysicalNumberOfCells() - 1) {
                        writer.write(",");
                    }
                }

                writer.write("\n");
            }

            writer.close();
            workbook.close();

            System.out.println("Excel file converted to CSV file successfully.");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

3. Replace `"path/to/your/excel/file.xlsx"` and `"path/to/your/csv/file.csv"` with the actual paths to your Excel and CSV files.

4. To run the converter, click on the "Run" button in IntelliJ IDEA or use the `mvn run` command in the terminal.

This will create a CSV file from your Excel file. You can then use the CSV file in your industry-level project.

