package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"

	"github.com/apache/avro/adapters/json"
	"github.com/apache/avro/avro"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run avro/avro_from_go.go filename.go struct_name")
		os.Exit(1)
	}

	file := os.Args[1]
	structName := os.Args[2]

	fileContent, err := os.ReadFile(file)
	if err != nil {
		fmt.Println("Error reading file:", err)
		os.Exit(1)
	}

	// Extract the struct definition from the Go code
	structDef, err := extractStructDef(string(fileContent), structName)
	if err != nil {
		fmt.Println("Error extracting struct definition:", err)
		os.Exit(1)
	}

	// Generate the Avro schema
	avroSchema, err := generateAvroSchema(structDef)
	if err != nil {
		fmt.Println("Error generating Avro schema:", err)
		os.Exit(1)
	}

	// Write the Avro schema to a file
	err = os.WriteFile("struct.avsc", avroSchema, 0644)
	if err != nil {
		fmt.Println("Error writing Avro schema to file:", err)
		os.Exit(1)
	}
}

func extractStructDef(goCode string, structName string) (string, error) {
	// Extract the struct definition from the Go code
	// Example: type MyStruct struct { Field1 string; Field2 int; }
	pattern := fmt.Sprintf("type %s struct {%s}", structName, strings.Join(strings.Fields(goCode), " "))
	match := strings.Match(goCode, pattern)
	if !match {
		return "", fmt.Errorf("could not find struct definition")
	}

	structDef := strings.TrimSpace(goCode[strings.Index(goCode, pattern):strings.Index(goCode, "}")+1])
	return structDef, nil
}

func generateAvroSchema(structDef string) (string, error) {
	// Generate the Avro schema from the struct definition
	// Example: { "type": "record", "name": "MyStruct", "fields": [ { "name": "Field1", "type": "string" }, { "name": "Field2", "type": "int" } ] }
	avroSchema := fmt.Sprintf("{ \"type\": \"record\", \"name\": \"%s\", \"fields\": [", structDef)
	for _, field := range strings.Fields(structDef) {
		avroSchema += fmt.Sprintf("{ \"name\": \"%s\", \"type\": \"%s\" },", field, strings.Split(field, " ")[1])
	}
	avroSchema = strings.TrimSuffix(avroSchema, ",")
	avroSchema += "] }"
	return avroSchema, nil
}

