        parent2 = selected_individuals((j + 1) % pop_size, :);
        offspring(j, :) = parent1 * selection_pressure + parent2 * (1 - selection_pressure);
        offspring(j, :) = offspring(j, :) + mutation_rate * randn(1, 2);
        offspring(j, :) = offspring(j, :) .* recombination_rate + (1 - recombination_rate) * parent1;
