# Define the domain name
$domain = "your_domain_name"

# Define the folder path to start the recursion
$folderPath = "C:\Path\To\Your\Folder"

# Function to check if a SID exists only in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $users = Get-ADUser -Filter {SID -eq $sid} -Properties SID, SIDHistory
    $groups = Get-ADGroup -Filter {SID -eq $sid} -Properties SID, SIDHistory

    if ($users.Count -gt 0) {
        foreach ($user in $users) {
            if ($user.SIDHistory.Count -gt 0) {
                $sidHistory = $user.SIDHistory -join ", "
                if ($sidHistory -eq $sid) {
                    return $true
                }
            }
        }
    }

    if ($groups.Count -gt 0) {
        foreach ($group in $groups) {
            if ($group.SIDHistory.Count -gt 0) {
                $sidHistory = $group.SIDHistory -join ", "
                if ($sidHistory -eq $sid) {
                    return $true
                }
            }
        }
    }

    return $false
}

# Recursively check the folders
function CheckFolders($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        $sidHistory = $acl.SidHistory
        $sidHistory = $sidHistory -join ", "

        if ($sidHistory -ne "") {
            $sidHistory = $sidHistory.Split(",")
            foreach ($sid in $sidHistory) {
                if (CheckSIDInSIDHistory($sid)) {
                    Write-Host "Folder: $($_.FullName) - ACL: $($acl.ToString()) - SID: $sid - SIDHistory: $sidHistory"
                }
            }
        }

        CheckFolders($_.FullName)
    }
}

# Start the recursion
